with remaining_keys as (select status from accounts intersect select status from accounts where balance >= 65000), reconciled as (select s.* from accounts s inner join remaining_keys k on s.status = k.status) select case when balance >= 63000 then 'HIGH' else 'LOW' end as balance_tier, sum(case when account_type = 'SAVINGS' then balance else 0 end) as savings_balance, avg(balance) filter (where status = 'FROZEN') as frozen_avg_balance, min(balance) as min_balance from reconciled group by 1 having min_balance > 0 order by min_balance desc
